const arabic={};document.querySelectorAll('[data-i18n]').forEach(el=>arabic[el.dataset.i18n]=el.textContent);document.querySelectorAll('[data-i18n-html]').forEach(el=>arabic[el.dataset.i18nHtml]=el.innerHTML);translations.ar=arabic;
function setLanguage(lang){const text=translations[lang];document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=text[el.dataset.i18n]);document.querySelectorAll('[data-i18n-html]').forEach(el=>el.innerHTML=text[el.dataset.i18nHtml]);const button=document.getElementById('language');button.textContent=lang==='ar'?'English ◎':'العربية ◎';button.setAttribute('aria-label',lang==='ar'?'Switch to English':'التبديل إلى العربية');document.title=lang==='ar'?'بُكرة | محاسبة المطاعم':'Bokrah | Restaurant accounting';document.querySelector('meta[name="description"]').content=lang==='ar'?'بُكرة لمحاسبة المطاعم. استكشف الواجهة وحمّل تطبيق ويندوز مباشرة.':'Bokrah restaurant accounting. Explore the interface and download the Windows application directly.';try{localStorage.setItem('bokrah-language',lang)}catch{} }
document.getElementById('language').onclick=()=>setLanguage(document.documentElement.lang==='ar'?'en':'ar');
